import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

export const useRegisterReceiptMutation = (options?: MutationOptions<any, CBDCAxiosError, any>) => {
  const registerBizNo = (registerBiz: any) => {
    //임시 parameter
    return resultify(axios.post<any>(`${API_URLS.receipt('/register/biz-no')}`, registerBiz));
  };

  const mutation = useMutation<any, CBDCAxiosError, any>({
    ...options,
    mutationFn: (registerBiz: any) => registerBizNo(registerBiz),
  });

  return {
    ...mutation,
  };
};
