import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

export const useDeleteReceiptMutation = (options?: MutationOptions<any, CBDCAxiosError, any>) => {
  const deleteBizNo = (cstmrNo: any) => {
    //임시 parameter
    return resultify(axios.post<any>(`${API_URLS.receipt('/remove/biz-no')}`, cstmrNo));
  };

  const mutation = useMutation<any, CBDCAxiosError, any>({
    ...options,
    mutationFn: (cstmrNo: any) => deleteBizNo(cstmrNo),
  });

  return {
    ...mutation,
  };
};
