import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

export const useCheckBizNoStatusMutation = (options?: MutationOptions<any, CBDCAxiosError, any>) => {
  const checkBizNoStatus = (bizNo: string) => {
    //임시 parameter
    return resultify(axios.post<any>(`${API_URLS.receipt(`/status/biz-no?bizNo=${bizNo}`)}`));
  };

  const mutation = useMutation<any, CBDCAxiosError, any>({
    ...options,
    mutationFn: (bizNo: string) => checkBizNoStatus(bizNo),
  });

  return {
    ...mutation,
  };
};
