import { zodResolver } from '@hookform/resolvers/zod';
import clsx from 'clsx';
import { useEffect, useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
//import { Inputs } from '~/entities/mobile-verification/model/types';
import { useLocation } from 'react-router-dom';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { Inputs } from '~/entities/business/model/types';
import { useCheckBizNoStatusMutation } from '~/entities/exchange/api/hooks/use-check-bizno-status-mutation';
import { useDeleteReceiptMutation } from '~/entities/exchange/api/hooks/use-delete-receipt-mutation';
import { useGetBizNoInformationMutation } from '~/entities/exchange/api/hooks/use-get-bizno-infomation-mutation';
import { useRegisterReceiptMutation } from '~/entities/exchange/api/hooks/use-register-receipt-mutation';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { RegisterBizNoFormSchema } from '~/entities/wallet/model/type';
import { StepBeforeRegister } from '~/shared/api/dtos/enums';
import { createFormOptions } from '~/shared/constants/form';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { notiBar } from '~/shared/lib/toast';
import { PATHS } from '~/shared/routes/paths';
import { closeDialog } from '~/shared/ui/dialogs';
import { TextInput } from '~/shared/ui/text-input/text-input';

type Props = {
  step?: StepBeforeRegister;
  aliasNm?: string;
};
export const BusinessAccountPage = () => {
  const { data: userRes, refetch: refetchUserInfo } = useGetUserInfoQuery();
  const { openAlertDialog } = useAlertDialog();
  const { navigate, navigateBack } = useNavigate();
  const { mutateAsync: receipt } = useRegisterReceiptMutation();
  const { mutateAsync: deleteReceipt } = useDeleteReceiptMutation();
  const { mutateAsync: checkBizNoStatus } = useCheckBizNoStatusMutation();
  const { mutateAsync: getBizNoInfo } = useGetBizNoInformationMutation();
  const { step, aliasNm } = ((useLocation().state as Props | null) ?? {}) as Props;
  const userBizNo = userRes?.tbCstmrMastr?.ewaBizNo;
  const cstmrNo = { cstmrNo: userRes?.tbCstmrMastr?.cstmrNo || '' };
  const formOptions = createFormOptions<Inputs>();

  const [isBusinessAccount] = useState<boolean>(step === StepBeforeRegister.재설정);
  const [SkipBtnFlag] = useState<boolean>(step === StepBeforeRegister.회원가입);
  const [isRegister] = useState<boolean>(step === StepBeforeRegister.등록);

  //true: from 회원가입 / false: from 재설정(마이페이지)

  const form = useForm<Inputs>({ mode: 'all', resolver: zodResolver(RegisterBizNoFormSchema) });
  const {
    register,
    handleSubmit,
    getValues,
    setValue,
    formState: { isValid },
  } = form;

  useSetHeaderTitle(i18n.t('manageBusinessAccount'));

  //유저 정보 갱신
  const syncUserInfo = async () => {
    await refetchUserInfo();
  };

  const validateBizNo = (bizNo: string) => {
    //개인/법인구분코드:4-5
    const mid = Number(bizNo.substring(3, 5));
    //개인사업자 조건
    const isPersonal = (mid >= 1 && mid <= 79) || mid === 80 || mid === 89 || (mid >= 90 && mid <= 99);

    return isPersonal;
  };

  const onSubmit = () => {
    const param = {
      ewaBizNo: getValues('businessNumber') || '',
      bizName: getValues('bizName'),
      ownerName: getValues('ownerName') || '',
      openDate: getValues('openDate') || '',
      aliasNm: aliasNm || '',
    };

    //if (!fnValidation(param)) return;

    setTimeout(async () => {
      openAlertDialog({
        message: '입력하신 정보로 등록하시겠습니까?',
        buttonLabel: [i18n.t('cancel'), i18n.t('confirm')],
        onConfirmClick: async () => {
          //개인사업자인지 check
          const isPersonalBiz = validateBizNo(param.ewaBizNo);
          if (!isPersonalBiz) {
            openAlertDialog({
              message: i18n.t('text:personalBusinessOnly'),
              onConfirmClick: () => {
                return;
              },
            });

            return;
          }

          await receipt(param);
          await syncUserInfo();
          notiBar(i18n.t('completerRegisterBizNo'));
          if (SkipBtnFlag) {
            //회원가입 루트에서 사업자 등록하는 경우 navateBack()이 아닌 메인페이지로 이동하기
            navigate(PATHS.home, { replace: true });
            return;
          }
          navigateBack();
        },
        onCancelClick: () => {
          //아무것도 수행하지 않음
        },
      });
    }, 0);
  };

  const requestRegisterBizNo = async () => {
    //const params: string = '1168119477';
    const param = {
      ewaBizNo: getValues('businessNumber') || '',
      bizName: getValues('bizName') || '',
      ownerName: getValues('ownerName') || '',
      openDate: getValues('openDate') || '',
    };

    openAlertDialog({
      //title: '사업자 정보 변경',
      message: i18n.t('validation:changeBusinessInfoConfirmation'),
      buttonLabel: [i18n.t('cancel'), i18n.t('change')],
      onConfirmClick: async () => {
        //개인사업자인지 check
        const isPersonalBiz = validateBizNo(param.ewaBizNo);
        if (!isPersonalBiz) {
          openAlertDialog({
            message: i18n.t('text:personalBusinessOnly'),
            onConfirmClick: () => {
              return;
            },
          });

          return;
        }

        setTimeout(async () => {
          //사업자정보변경은 신규등록
          await receipt(param);
          await syncUserInfo();
          notiBar(i18n.t('completeChangeBizNo'));
          navigateBack();
        }, 0);
      },
      onCancelClick: () => {
        // 취소 시 아무 작업 없음
      },
    });
    //return await receipt(params);
  };

  useEffect(() => {
    //userRes에 bizno가 있으면 status 검색
    if (isBusinessAccount) {
      setTimeout(async () => {
        //await checkBizNoStatus('1168119477').then((response) => {
        await getBizNoInfo(userBizNo).then((response) => {
          setValue('businessNumber', response.ewaBizNo);
          setValue('bizName', response.bizName);
          setValue('ownerName', response.ownerName);
          setValue('openDate', response.openDate);
        });
      }, 0);
    }
  }, []);

  return (
    <div className="wrap bgw">
      <div className="content sub has-btm-btn">
        {/* {aliasNm && <div className="business-account-page__selected-wallet">선택 지갑 : {aliasNm}</div>} */}
        <div className="sub-desc business-account-page__desc">
          <p
            dangerouslySetInnerHTML={{
              __html: i18n.t('createBusinessAccount'),
            }}
          />
          <p
            className="business-account-page__notice"
            style={{ fontSize: 'var(--font-size-13)' }}
            dangerouslySetInnerHTML={{
              __html: i18n.t('text:receiptNotice1'),
            }}
          ></p>
        </div>
        <FormProvider {...form}>
          <form onSubmit={handleSubmit(onSubmit)} className="ipt-form-area">
            <TextInput
              label={i18n.t('businessNumber')}
              {...register('businessNumber', formOptions.BUSINESS_NUMBER)}
              maxLength={10}
              isErrorPaddingPresent={false}
            />
            <TextInput label={i18n.t('bizName')} {...register('bizName')} isErrorPaddingPresent={false} />
            <TextInput label={i18n.t('name')} {...register('ownerName')} isErrorPaddingPresent={false} />
            <TextInput
              label={i18n.t('openDate')}
              {...register('openDate')}
              isErrorPaddingPresent={false}
              maxLength={8}
              placeholder="개업연월일 8자리(YYYYMMDD)"
            />
            <span> {i18n.t('text:receiptNotice2')} </span>
            <p
              dangerouslySetInnerHTML={{
                __html: i18n.t('text:receiptNotice3'),
              }}
              onClick={() => {
                openAlertDialog({
                  //message: i18n.t('validation:deleteBusinessInfoConfirmation'),
                  message: '외부페이지로 이동합니다.',
                  buttonLabel: ['취소', '이동'],
                  onConfirmClick: async () => {
                    window.open('https://www.kftcvan.or.kr/');
                  },
                  onCancelClick: () => {
                    // 취소 시 아무 작업 없음
                  },
                });
              }}
            />
            <span> {i18n.t('text:receiptNotice4')} </span>
            <span> {i18n.t('text:receiptNotice5')} </span>
            {isBusinessAccount && ( //사업자정보삭제 문구 기존 사업자의 경우에만
              <span className="business-account-page__inline-text">
                -{' '}
                <span
                //style={{ display: 'inline-block', color: '#0068b7', whiteSpace: 'nowrap', fontWeight: 'bold' }}
                // onClick={() => {
                //   openAlertDialog({
                //     message: i18n.t('validation:deleteBusinessInfoConfirmation'),
                //     buttonLabel: ['취소', '삭제'],
                //     onConfirmClick: async () => {
                //       console.log('사업자 정보 삭제');
                //       await deleteReceipt(cstmrNo);
                //       notiBar(i18n.t('completeDeleteBizNo'));
                //       navigateBack();
                //     },
                //     onCancelClick: () => {
                //       // 취소 시 아무 작업 없음
                //     },
                //   });
                // }}
                >
                  사업자 정보 삭제
                </span>{' '}
                시, 현금영수증 발급이 불가합니다.
              </span>
            )}
          </form>
        </FormProvider>
      </div>
      <div className={`btm-btn-area ${!isRegister ? 'confirm half' : ''}`}>
        {/* <div className={`btm-btn-area confirm half`}> */}
        {/* ✅ 건너뛰기 버튼 회원가입 진입시에만 */}
        {SkipBtnFlag && (
          <button
            onClick={() => {
              openAlertDialog({
                title: '사업자 등록 건너뛰기',
                message: '사업자 등록을 취소하시겠습니까?',
                buttonLabel: ['취소', '확인'],
                onConfirmClick: () => {
                  closeDialog(() => {
                    navigate(PATHS.home, { replace: true });
                  });
                },
                onCancelClick: () => {
                  // 취소 시 아무 작업 없음
                },
              });
            }}
            type="button"
            className={clsx('btm-btn', { disabled: false })}
            id="charge"
            disabled={false}
          >
            {i18n.t('skip')}
          </button>
        )}
        {isBusinessAccount ? ( //사업자계정일경우 '삭제/저장'
          <>
            <button
              onClick={() => {
                //사업자정보 삭제
                openAlertDialog({
                  message: i18n.t('validation:deleteBusinessInfoConfirmation'),
                  buttonLabel: ['취소', '삭제'],
                  onConfirmClick: async () => {
                    await deleteReceipt(cstmrNo);
                    await syncUserInfo();
                    notiBar(i18n.t('completeDeleteBizNo'));
                    navigateBack();
                  },
                  onCancelClick: () => {
                    // 취소 시 아무 작업 없음
                  },
                });
              }}
              type="button"
              className={clsx('btm-btn', { disabled: false })}
              id="charge"
              disabled={false}
            >
              {i18n.t('deleteBusinessAccount')}
            </button>
            <button
              onClick={requestRegisterBizNo} //변경
              type="button"
              className={clsx('btm-btn app', { disabled: false })}
              id="charge"
              disabled={false}
            >
              {i18n.t('save')}
            </button>
          </>
        ) : (
          //사업자계정으로 전환(신규)일경우 '등록'
          <button
            onClick={handleSubmit(onSubmit)} //등록
            type="button"
            className={clsx('btm-btn app', { disabled: false })}
            id="charge"
            disabled={false}
          >
            {i18n.t('register')}
          </button>
        )}
      </div>
    </div>
  );
};
